-- YellowRose (yellowrosedistilling.com/products/) — applied 2026-10-11. part1 then inserts_1.
update cellar.products set mash_style = 'traditional', mash_bill = '100% Corn', specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://yellowrosedistilling.com/wp-content/uploads/2023/11/YR-Outlaw-Bourbon_HR_web-min.png'), name = 'Yellow Rose Outlaw Bourbon', expression = 'Outlaw Bourbon', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Outlaw Bourbon')) a), producer = coalesce(producer, 'Yellow Rose'), producer_id = coalesce(producer_id, '442efe51-4552-429c-8cd2-6954672d4290'::uuid), source = 'maker', source_url = 'https://yellowrosedistilling.com/products/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '407bf297-3674-466d-bad6-db520db56008' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('407bf297-3674-466d-bad6-db520db56008');
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
